    private val candles = close.indices.map { Candle(it * 86_400_000L, if (it == 0) close[0] - 0.5 else close[it - 1], high[it], low[it], close[it], 1000.0) }

    private fun near(exp: Double, got: Double, tol: Double = 1e-6) = assertEquals(exp, got, tol)

    @Test fun sma() { val v = Indicators.sma(close, 20); near(120.78820507, v[60]); near(118.10085099, v[90]); near(133.23862653, v[119]); assertTrue(v[18].isNaN()) }
    @Test fun ema() { val v = Indicators.ema(close, 12); near(125.25454502, v[60]); near(121.80269273, v[90]); near(130.12536159, v[119]); near(130.125362, v[119], 1e-5) }
    @Test fun rsi() { val v = Indicators.rsi(close, 14); near(75.59431601, v[60]); near(84.88074990, v[90]); near(24.41597342, v[119]); near(24.425614, v[119], 0.05) }
    @Test fun bollinger() { val b = Indicators.bollinger(close); near(135.45541929, b.upper[60]); near(127.10262415, b.upper[90]); near(140.80476111, b.upper[119]) }
    @Test fun atr() { val v = Indicators.atr(candles, 14); near(4.29100191, v[60]); near(4.38593690, v[90]); near(4.29153822, v[119]); near(4.291503, v[119], 1e-3) }
    @Test fun macd() { val h = Indicators.macd(close).hist; near(0.35122474, h[60]); near(1.59843014, h[90]); near(-1.59175499, h[119]) }

    @Test fun rsiBounds() {
        val up = DoubleArray(60) { 10.0 + it }
        assertEquals(100.0, Indicators.last(Indicators.rsi(up)), 1e-9)
        val flat = DoubleArray(60) { 5.0 }
        assertEquals(100.0, Indicators.last(Indicators.rsi(flat)), 1e-9) // aucune perte : convention 100
    }

    @Test fun adxTrend() {
        val c = (0 until 120).map { Candle(it * 86_400_000L, 100.0 + it, 101.0 + it, 99.0 + it, 100.5 + it, 1.0) }
        val a = Indicators.adx(c)
        assertTrue(Indicators.last(a.adx) > 25)
        assertTrue(Indicators.last(a.plusDi) > Indicators.last(a.minusDi))
    }

    @Test fun fibonacciAndLevels() {
        val f = Indicators.fibonacci(candles)!!
        assertTrue(f.levels.all { it.second in f.low..f.high })
        val lv = Indicators.levels(candles, close.last())
        assertTrue(lv.all { it.touches >= 2 })
    }

    @Test fun aggregateWeekly() {
        val w = Indicators.aggregate(candles.take(14)) { it / (7 * 86_400_000L) }
        assertEquals(2, w.size)
        assertEquals(candles[6].close, w[0].close, 1e-12)
        assertEquals(candles.take(7).maxOf { it.high }, w[0].high, 1e-12)
    }
}
